{"content": "import yaml


def restore_workspace_from_yaml(state_yaml: str) -> dict:
    """Parse a YAML string and return the workspace state as a dictionary.

    Uses yaml.safe_load to prevent arbitrary code execution from
    untrusted YAML input.
    """
    result = yaml.safe_load(state_yaml)
    if result is None:
        return {}
    if not isinstance(result, dict):
        raise ValueError(
            f"Expected YAML to deserialize to a dict, got {type(result).__name__}"
        )
    return result
